"""Generate src/cli/shorthand/tests.rs from the reference's
tests/unit/test_shorthand.py cases and its ShorthandParser.

    PYTHONPATH=$AWSR_REFERENCE_SRC python3 src/cli/testdata/gen_shorthand_tests.py \
        > src/cli/shorthand/tests.rs
"""

import json
import sys

import awscli  # noqa: F401
from awscli import shorthand

sys.path.insert(0, sys.argv[1] if len(sys.argv) > 1 else '.')


class _Mark:
    def __getattr__(self, name):
        return lambda *a, **k: (lambda f: f)


class _Pytest:
    mark = _Mark()


sys.modules.setdefault('pytest', _Pytest())
from tests.unit.test_shorthand import PARSING_TEST_CASES  # noqa: E402

ERRORS = [
    'foo', 'foo="bar', '"foo=bar', "foo='bar", "foo=[bar", "foo={bar",
    "foo={bar}", "foo={bar=bar", "foo=bar,", "foo==bar,\nbar=baz",
    'foo=bar,foo=qux', 'foo="' + '\\' * 100, "foo='" + '\\' * 100,
]

# Inputs whose outcome (value or error) is taken from the reference.
EXTRA = [
    'a=b,c', 'a=b,,c=d', 'a=,', '=b', 'a=[b,c', 'a={b=c,d}', 'a=b, c=d,',
    "a='b\\'", 'a=b,\nb=c,\nb=d', 'a=x\n,a=y',
]


def rs(s):
    return json.dumps(s, ensure_ascii=False)


def main():
    out = []
    w = out.append
    w('//! Generated by `src/cli/testdata/gen_shorthand_tests.py` from the')
    w("//! reference's `tests/unit/test_shorthand.py`. Do not edit.")
    w('')
    w('use super::*;')
    w('use crate::cli::pyjson;')
    w('')
    w('/// (input, expected value as JSON).')
    w('const PARSING: &[(&str, &str)] = &[')
    extra_ok, extra_err = [], []
    for data in EXTRA:
        try:
            extra_ok.append((data, shorthand.ShorthandParser().parse(data)))
        except shorthand.ShorthandParseError:
            extra_err.append(data)
    for data, expected in list(PARSING_TEST_CASES) + extra_ok:
        actual = shorthand.ShorthandParser().parse(data)
        assert actual == expected, data
        w(f'    ({rs(data)}, {rs(json.dumps(expected, ensure_ascii=False))}),')
    w('];')
    w('')
    w('/// (input, `str(ShorthandParseError)`).')
    w('const ERRORS: &[(&str, &str)] = &[')
    for data in ERRORS + extra_err:
        try:
            shorthand.ShorthandParser().parse(data)
        except shorthand.ShorthandParseError as e:
            w(f'    ({rs(data)}, {rs(str(e))}),')
        else:
            raise AssertionError(data)
    w('];')
    w('')
    w('#[test]')
    w('fn parses_like_the_reference() {')
    w('    for (input, expected) in PARSING {')
    w('        let actual = ShorthandParser::parse(input).unwrap_or_else(|e| panic!("{input:?}: {e:?}"));')
    w('        assert_eq!(actual, pyjson::loads(expected).unwrap(), "{input:?}");')
    w('    }')
    w('}')
    w('')
    w('#[test]')
    w('fn errors_like_the_reference() {')
    w('    for (input, expected) in ERRORS {')
    w('        match ShorthandParser::parse(input) {')
    w('            Err(ShorthandError::Parse(m)) => assert_eq!(m, *expected, "{input:?}"),')
    w('            other => panic!("{input:?}: {other:?}"),')
    w('        }')
    w('    }')
    w('}')
    print('\n'.join(out))


if __name__ == '__main__':
    main()
